/* CSS PART 1 OF 3 */

/* DESIGN TOKENS */
:root {
  color-scheme: light;
  --ink: #202b30;
  --ink-soft: #536168;
  --navy: #243941;
  --navy-deep: #192b32;
  --accent: #bd713e;
  --accent-dark: #99542e;
  --paper: #f7f6f2;
  --white: #ffffff;
  --line: #deded7;
  --muted: #eeede7;

  --font-display: Georgia, "Times New Roman", serif;
  --font-body: "Helvetica Neue", Helvetica, Arial, sans-serif;

  --container: 1200px;
  --gutter: clamp(20px, 5vw, 76px);
  --radius: 5px;
  --shadow: 0 14px 40px rgba(25, 43, 50, 0.12);

  --space-1: 8px;
  --space-2: 16px;
  --space-3: 24px;
  --space-4: 32px;
  --space-5: 48px;
  --space-6: 72px;
  --space-7: 104px;
}

/* RESET */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

img,
picture,
svg {
  display: block;
  max-width: 100%;
}

img {
  height: auto;
}

button,
input,
textarea,
select {
  font: inherit;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

::selection {
  background: var(--accent);
  color: var(--white);
}

/* ACCESSIBILITY */
:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 4px;
}

.skip-link {
  position: absolute;
  z-index: 1000;
  top: 12px;
  left: 12px;
  padding: 12px 18px;
  transform: translateY(-160%);
  background: var(--white);
  color: var(--ink);
  border: 2px solid var(--accent);
}

.skip-link:focus {
  transform: translateY(0);
}

/* TYPOGRAPHY */
h1,
h2,
h3,
h4,
p {
  margin-top: 0;
}

h1,
h2,
h3 {
  color: var(--navy-deep);
  font-family: var(--font-display);
  font-weight: 400;
  line-height: 1.12;
  letter-spacing: -0.035em;
}

h1 {
  font-size: clamp(2.8rem, 6.2vw, 5.8rem);
}

h2 {
  font-size: clamp(2.15rem, 4vw, 3.6rem);
}

h3 {
  font-size: clamp(1.4rem, 2.4vw, 2rem);
}

p {
  margin-bottom: 1.25em;
}

.lead {
  max-width: 620px;
  color: var(--ink-soft);
  font-size: clamp(1.05rem, 1.5vw, 1.2rem);
  line-height: 1.75;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 18px;
  color: var(--accent-dark);
  font-size: 0.73rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 28px;
  height: 2px;
  background: currentColor;
  content: "";
}

.text-muted {
  color: var(--ink-soft);
}

/* PAGE STRUCTURE */
.container {
  width: min(100% - (var(--gutter) * 2), var(--container));
  margin-inline: auto;
}

.section {
  padding-block: var(--space-7);
}

.section-heading {
  max-width: 720px;
  margin-bottom: var(--space-5);
}

.section-heading h2 {
  margin-bottom: 18px;
}

.section-heading p {
  max-width: 590px;
  color: var(--ink-soft);
}

/* HEADER AND NAVIGATION */
.site-header {
  position: relative;
  z-index: 50;
  background: var(--white);
  border-bottom: 1px solid rgba(32, 43, 48, 0.1);
}

.header-inner {
  display: flex;
  width: min(100% - (var(--gutter) * 2), 1360px);
  min-height: 88px;
  margin-inline: auto;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
}

.brand {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 13px;
}

.brand img {
  width: auto;
  max-width: 210px;
  max-height: 62px;
  object-fit: contain;
}

.brand-name {
  color: var(--navy-deep);
  font-family: var(--font-display);
  font-size: 1.15rem;
  line-height: 1.15;
}

.brand-name small {
  display: block;
  margin-top: 5px;
  color: var(--ink-soft);
  font-family: var(--font-body);
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.main-nav {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: clamp(16px, 2.4vw, 34px);
}

.main-nav a:not(.button) {
  color: var(--ink);
  font-size: 0.84rem;
  font-weight: 650;
  transition: color 180ms ease;
}

.main-nav a:not(.button):hover {
  color: var(--accent-dark);
}

.header-contact {
  display: flex;
  flex-shrink: 0;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
}

.header-contact a {
  color: var(--navy-deep);
  font-size: 1rem;
  font-weight: 800;
}

.header-contact span {
  color: var(--ink-soft);
  font-size: 0.68rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

/* BUTTONS */
.button {
  display: inline-flex;
  min-height: 52px;
  padding: 13px 23px;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: var(--accent);
  color: var(--white);
  font-size: 0.83rem;
  font-weight: 800;
  letter-spacing: 0.025em;
  line-height: 1.3;
  text-align: center;
  cursor: pointer;
  transition:
    background 180ms ease,
    border-color 180ms ease,
    color 180ms ease,
    transform 180ms ease;
}

.button:hover {
  transform: translateY(-2px);
  background: var(--accent-dark);
}

.button-primary {
  background: var(--accent);
  color: var(--white);
}

.button-secondary {
  border-color: rgba(255, 255, 255, 0.65);
  background: transparent;
  color: var(--white);
}

.button-secondary:hover {
  border-color: var(--white);
  background: var(--white);
  color: var(--navy-deep);
}

.button-dark {
  background: var(--navy);
  color: var(--white);
}

.button-dark:hover {
  background: var(--navy-deep);
}

.button-light {
  border-color: var(--line);
  background: var(--white);
  color: var(--navy-deep);
}

.button-light:hover {
  border-color: var(--navy);
  background: var(--navy);
  color: var(--white);
}

/* HERO */
.hero {
  position: relative;
  display: grid;
  min-height: min(760px, calc(100svh - 88px));
  grid-template-columns: 1fr 0.92fr;
  overflow: hidden;
  background: var(--navy-deep);
  color: var(--white);
}

.hero-content {
  position: relative;
  z-index: 2;
  display: flex;
  padding: clamp(52px, 8vw, 112px) 0 clamp(52px, 8vw, 100px) var(--gutter);
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
}

.hero .eyebrow {
  color: #e4a477;
}

.hero h1 {
  max-width: 690px;
  margin-bottom: 26px;
  color: var(--white);
}

.hero .lead {
  max-width: 540px;
  margin-bottom: 34px;
  color: #d4dddf;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 13px;
}

.hero-proof {
  display: flex;
  margin-top: 48px;
  padding-top: 22px;
  flex-wrap: wrap;
  gap: 24px;
  border-top: 1px solid rgba(255, 255, 255, 0.22);
  color: #d4dddf;
  font-size: 0.8rem;
}

.hero-proof strong {
  color: var(--white);
  font-weight: 800;
}

.hero-media {
  position: relative;
  min-height: 540px;
  overflow: hidden;
  background: #34474b;
}

.hero-media::after {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    rgba(25, 43, 50, 0.2),
    transparent 38%
  );
  content: "";
  pointer-events: none;
}

.hero-media img {
  width: 100%;
  height: 100%;
  min-height: inherit;
  object-fit: cover;
  object-position: center;
}

.hero-caption {
  position: absolute;
  z-index: 2;
  right: 24px;
  bottom: 24px;
  max-width: 260px;
  padding: 13px 17px;
  background: var(--white);
  color: var(--navy-deep);
  font-size: 0.76rem;
  font-weight: 750;
  line-height: 1.5;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}
