/* CSS PART 3 OF 3 */

/* CONTACT AND CONVERSION */
.contact-section {
  padding-block: var(--space-7);
  background: var(--navy-deep);
  color: var(--white);
}

.contact-section h2,
.contact-section h3 {
  color: var(--white);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: clamp(45px, 8vw, 105px);
}

.contact-copy {
  position: sticky;
  top: 35px;
}

.contact-copy .eyebrow {
  color: #e4a477;
}

.contact-copy h2 {
  margin-bottom: 22px;
}

.contact-copy > p {
  color: #d4dddf;
}

.contact-details {
  display: grid;
  gap: 22px;
  margin-top: 38px;
}

.contact-detail {
  display: flex;
  align-items: flex-start;
  gap: 15px;
}

.contact-detail-icon {
  display: flex;
  width: 42px;
  height: 42px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255, 255, 255, 0.3);
  color: #e4a477;
}

.contact-detail span {
  display: block;
  color: #c7d0d1;
  font-size: 0.75rem;
}

.contact-detail a {
  display: inline-block;
  margin-top: 3px;
  color: var(--white);
  font-weight: 750;
}

.contact-form-wrap {
  padding: clamp(25px, 4vw, 45px);
  background: var(--white);
  color: var(--ink);
  box-shadow: var(--shadow);
}

.contact-form-wrap h3 {
  margin-bottom: 10px;
  color: var(--navy-deep);
  font-size: 1.9rem;
}

.contact-form-intro {
  margin-bottom: 28px;
  color: var(--ink-soft);
  font-size: 0.9rem;
}

.contact-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 19px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 7px;
}

.form-field-full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--navy-deep);
  font-size: 0.8rem;
  font-weight: 750;
}

.form-field input,
.form-field textarea,
.form-field select {
  width: 100%;
  min-height: 49px;
  padding: 12px 14px;
  border: 1px solid #d4d7d3;
  border-radius: 2px;
  background: #fbfbf9;
  color: var(--ink);
  outline-offset: 2px;
  transition: border-color 180ms ease;
}

.form-field textarea {
  min-height: 135px;
  resize: vertical;
}

.form-field input:hover,
.form-field textarea:hover,
.form-field select:hover {
  border-color: var(--accent);
}

.form-field input:focus,
.form-field textarea:focus,
.form-field select:focus {
  border-color: var(--accent-dark);
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #858c8d;
}

.contact-form .button {
  width: 100%;
  grid-column: 1 / -1;
  border: 0;
}

.form-note {
  grid-column: 1 / -1;
  margin: -5px 0 0;
  color: var(--ink-soft);
  font-size: 0.75rem;
  line-height: 1.6;
}

/* FOOTER */
.site-footer {
  padding-block: 35px;
  background: #14252b;
  color: #c7d0d1;
}

.footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
}

.footer-brand {
  color: var(--white);
  font-family: var(--font-display);
  font-size: 1.1rem;
}

.footer-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 20px;
  font-size: 0.77rem;
}

.footer-meta a:hover {
  color: #e4a477;
}

/* TABLET */
@media (max-width: 1050px) {
  :root {
    --space-7: 80px;
  }

  .header-inner {
    min-height: 78px;
    flex-wrap: wrap;
    gap: 15px;
    padding-block: 12px;
  }

  .brand img {
    max-width: 175px;
